sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float complexity;
uniform float twist;
uniform float speed;
uniform float contrast;
layout(color) uniform half4 colorA;
layout(color) uniform half4 colorB;
uniform float hueCycle;
uniform float blend;
uniform float amount;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 rgb2hsv(float3 c) {
    float4 K = float4(0.0, -0.3333333, 0.6666667, -1.0);
    float4 p = mix(float4(c.b, c.g, K.w, K.z), float4(c.g, c.b, K.x, K.y), step(c.b, c.g));
    float4 q = mix(float4(p.x, p.y, p.w, c.r), float4(c.r, p.y, p.z, p.x), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    return float3(abs(q.z + (q.w - q.y) / (6.0 * d + 0.0000001)), d / (q.x + 0.0000001), q.x);
}
float3 hsv2rgb(float3 c) {
    float3 p = abs(fract(float3(c.x) + float3(1.0, 0.6666667, 0.3333333)) * 6.0 - 3.0);
    return c.z * mix(float3(1.0), saturate(p - 1.0), c.y);
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 p = (coord - size * 0.5) / max(scale, 1.0);
    float t = time * speed;
    float r = length(p);
    p = rot2(p, twist * r);
    float v = sin(p.x * complexity + t) + sin(p.y * complexity * 1.3 + t * 1.3) + sin((p.x + p.y) * complexity * 0.7 + t * 0.7) + sin(r * complexity * 1.6 - t);
    v = saturate((v * 0.25 + 0.5 - 0.5) * contrast + 0.5);
    float3 layer = mix(float3(colorA.rgb), float3(colorB.rgb), v);
    float3 h = rgb2hsv(layer);
    h.x = fract(h.x + hueCycle * (0.5 + 0.5 * sin(t * 0.5)));
    layer = hsv2rgb(h);
    float3 o = mix(s, blendm(s, layer, blend), amount);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), 1.0);
}
